(()=>{
 const P=R.platform,E=R.esc,tr=(az,ru,en)=>({az,ru,en}[R.lang]||az),owner=()=>R.state.user?.is_owner;
 const field=(label,name,value='',extra='')=>`<label class="field">${E(label)}<input name="${name}" value="${E(value)}" ${extra}></label>`;
 let cache=new Map(),clinicId='';
 function resource(path){const key=R.state.user?.id+path;if(!cache.has(key)){const entry={};cache.set(key,entry);R.request(path).then(data=>{entry.data=data;if(cache.get(key)===entry)R.render();}).catch(e=>{entry.error=e.message;R.render();});}return cache.get(key);}
 const pending=e=>`<section class="card" role="status">${E(e.error||tr('Yüklənir…','Загрузка…','Loading…'))}</section>`;
 function connection(){const isAdmin=R.state.route==='/admin/clinics',list=resource(isAdmin?'/admin/clinics':'/me/clinics');if(!list.data)return P.accountShell(tr('Klinika bağlantıları','Подключения клиник','Clinic connections'),pending(list));if(!list.data.some(c=>c.id===clinicId))clinicId=list.data[0]?.id||'';
 const title=tr('Klinika bağlantıları','Подключения клиник','Clinic connections'),select=`<div class="pro-page-heading"><div><span class="eyebrow">RADAZ · DICOM</span><h1>${title}</h1></div><a class="btn btn-outline" href="#/dashboard" data-action="openMyProfile">${tr('Klinikalarım','Мои клиники','My clinics')}</a></div><section class="card"><label class="field">${tr('Klinika seçin','Выберите клинику','Select clinic')}<select id="connection-clinic">${list.data.map(c=>`<option value="${E(c.id)}" ${c.id===clinicId?'selected':''}>${E(c.name)}</option>`).join('')}</select></label></section>`;
 if(!clinicId)return P.accountShell(title,select+`<section class="card"><p>${tr('Əvvəlcə həkim profilindən klinika əlavə edin.','Сначала добавьте клинику в профиле врача.','First add a clinic from your doctor profile.')}</p></section>`);
 const path=(isAdmin?'/admin':'/me')+'/clinics/'+clinicId+'/connection',item=resource(path);if(!item.data)return P.accountShell(title,select+pending(item));const d=item.data,s=d.settings;
 return P.accountShell(title,select+`<div class="pro-connection-grid"><section class="card"><div class="pro-section-heading"><h2>${E(d.clinic.name)}</h2><span class="pro-status ${s.enabled?'on':''}">${s.enabled?tr('Qəbul aktivdir','Приём включён','Receiving enabled'):tr('Qəbul bağlıdır','Приём выключен','Receiving disabled')}</span></div><form data-form="clinicConnection"><input type="hidden" name="path" value="${E(path)}"><div class="form-grid">${field(tr('Klinikadakı serverin IP / adı','IP / имя сервера клиники','Clinic server IP / name'),'server_host',s.server_host,'placeholder="192.168.1.10"')}${field('RADAZ AE Title','ae_title',s.ae_title,'required maxlength="16" pattern="[A-Za-z0-9_-]+"')}${field(tr('Qəbuledicinin dinləmə IP-si','IP прослушивания','Receiver bind IP'),'listen_host',s.listen_host,'required placeholder="0.0.0.0"')}${field('DICOM TCP port','dicom_port',s.dicom_port,'required type="number" min="1024" max="65535"')}</div><label class="field">${tr('İcazəli cihazların AE Title siyahısı','AE Title разрешённых устройств','Allowed device AE Titles')}<textarea name="source_ae_titles" rows="3" placeholder="CT_SCANNER&#10;MRI_SCANNER">${E(s.source_ae_titles.join('\n'))}</textarea></label><label class="field">${tr('İcazəli cihazların IP siyahısı','IP разрешённых устройств','Allowed device IP addresses')}<textarea name="source_ips" rows="3" placeholder="192.168.1.20&#10;192.168.1.21">${E(s.source_ips.join('\n'))}</textarea></label><label class="check-field"><input type="checkbox" name="enabled" ${s.enabled?'checked':''}>${tr('Bu klinikadan müayinə qəbulunu aktiv et','Разрешить приём из этой клиники','Enable study intake from this clinic')}</label><button class="btn btn-primary" type="submit">${tr('Bağlantı ayarlarını saxla','Сохранить подключение','Save connection settings')}</button></form></section><aside><section class="card pro-flow"><h2>${tr('Göndəriş yolu','Путь отправки','Transfer path')}</h2><ol><li><strong>CT / MRT / PACS</strong><span>${tr('Cihazın DICOM göndəriş menyusu','DICOM-отправка на устройстве','Device DICOM send menu')}</span></li><li><strong>${E(s.server_host||tr('Klinikanın lokal serveri','Локальный сервер клиники','Clinic local server'))}</strong><span>${E(s.ae_title)} · TCP ${s.dicom_port}</span></li><li><strong>RADAZ</strong><span>${tr('Müayinə klinikanın həkiminə təyin olunur','Исследование поступает врачу клиники','Study is assigned to the clinic’s doctor')}</span></li></ol><p>${tr('Cihazda Destination AE, IP və portu bu ayarlara uyğun yazın. Saytın HTTPS ünvanı cihazın DICOM portu deyil; klinikada qəbuledici proqram işləməlidir.','Укажите на устройстве Destination AE, IP и порт. HTTPS-адрес сайта не является DICOM-портом; в клинике должен работать приёмник.','Set the device destination AE, IP and port. The website HTTPS address is not a DICOM port; the clinic receiver must be running.')}</p></section><section class="card"><h2>${tr('Qəbuledici bağlantısı','Подключение приёмника','Receiver connection')}</h2><p>${d.has_key?tr('Bağlantı açarı yaradılıb.','Ключ создан.','Connection key exists.'):tr('Bağlantı açarı hələ yaradılmayıb.','Ключ ещё не создан.','No connection key yet.')}</p><p>${tr('Son qəbul','Последний приём','Last received')}: <strong>${d.last_received_at?E(new Date(d.last_received_at).toLocaleString()):'—'}</strong></p><button class="btn btn-primary" data-action="bridgeConfig" data-path="${E(path)}" ${!s.enabled?'disabled':''}>${tr('Bağlantı faylı yarat','Создать файл подключения','Create connection file')}</button><p class="tiny-text">${tr('Yeni fayl köhnə açarı ləğv edir. Faylın içində gizli açar var; yalnız klinikanın serverində saxlayın.','Новый файл отменяет старый ключ. Файл содержит секрет; храните его только на сервере клиники.','A new file revokes the previous key. It contains a secret; keep it only on the clinic server.')}</p>${d.has_key?`<button class="btn btn-outline" data-action="revokeBridge" data-path="${E(path)}">${tr('Bağlantı açarını ləğv et','Отозвать ключ','Revoke connection key')}</button>`:''}<details><summary>${tr('Quraşdırma addımları','Установка','Setup steps')}</summary><p>1. ${tr('Repository-də integrations/clinic/setup.ps1 faylını başladın. Python venv yaradılacaq.','Запустите integrations/clinic/setup.ps1 из репозитория. Будет создан Python venv.','Run integrations/clinic/setup.ps1 from the repository. It creates a Python venv.')}</p><p>2. ${tr('Yüklənən radaz-clinic.json faylını həmin qovluğa qoyun.','Поместите скачанный radaz-clinic.json в эту папку.','Place the downloaded radaz-clinic.json in that folder.')}</p><p>3. <code>.venv/Scripts/python.exe bridge.py --config radaz-clinic.json --check</code></p><p>4. <code>.venv/Scripts/python.exe bridge.py --config radaz-clinic.json</code></p><p>${tr('PACS və ya cihazdan bu AE Title və porta göndərin. Şəbəkə cihazı üçün dinləmə IP-si lokal şəbəkə IP-si və ya 0.0.0.0 olmalıdır.','Отправляйте с PACS или устройства на этот AE Title и порт. Для сети укажите локальный IP или 0.0.0.0.','Send from PACS or the device to this AE Title and port. For LAN devices bind to the LAN IP or 0.0.0.0.')}</p></details></section></aside></div>`);
 }
 R.forms.clinicConnection=async d=>{await R.request(d.path,{method:'PUT',body:{...d,enabled:d.enabled==='on'}});cache.clear();R.render();R.toast(tr('Bağlantı ayarları saxlanıldı.','Подключение сохранено.','Connection settings saved.'));};
 R.actions.bridgeConfig=async el=>{const d=await R.request(el.dataset.path+'/key',{method:'POST',body:{}}),s=d.settings;R.download(JSON.stringify({endpoint:d.endpoint,api_key:d.key,...s,idle_seconds:120,spool_dir:'./spool'},null,2),'radaz-clinic.json','application/json');cache.clear();R.render();};
 R.actions.revokeBridge=async el=>{await R.request(el.dataset.path+'/revoke',{method:'POST',body:{}});cache.clear();R.render();};
 R.actions.openClinicConnection=el=>{clinicId=el.dataset.id;cache.clear();R.go('/clinic-connections');};
 document.addEventListener('change',e=>{if(e.target.id==='connection-clinic'){clinicId=e.target.value;R.render();}});
 const profile=R.profileDashboard;R.profileDashboard=()=>{const el=document.createElement('div');el.innerHTML=profile();const price=el.querySelector('[name="price"]');if(price&&R.state.myProfile?.price_managed&&!owner()){price.readOnly=true;price.closest('label').insertAdjacentHTML('beforeend',`<small>${tr('Qiyməti administrator təyin edir.','Цену задаёт администратор.','Price is set by the administrator.')}</small>`);}el.querySelector('#my-clinics')?.insertAdjacentHTML('beforeend',`<div class="pro-clinic-connections">${(R.state.clinics||[]).map(c=>`<a class="btn btn-outline" href="#/clinic-connections" data-action="openClinicConnection" data-id="${E(c.id)}">${E(c.name)} · ${tr('Bağlantı ayarları','Подключение','Connection settings')}</a>`).join('')}</div>`);return el.innerHTML;};
 const cases=R.casesDashboard;R.casesDashboard=()=>{const html=cases();if(owner())return html;const data=P.financeResource('/me/earnings').data;if(!data)return html;const money=P.financeMoney;return `<a class="pro-doctor-balance" href="#/earnings"><div><span>${tr('Bu ay qazancım','Мой заработок за месяц','My earnings this month')}</span><strong>${money(data.total.amount)}</strong></div><div><span>${tr('Tamamlanmış rapor','Завершённые заключения','Completed reports')}</span><strong>${data.total.count}</strong></div><div><span>${tr('Konsultasiya qiymətim','Моя цена консультации','My consultation price')}</span><strong>${money(data.consultation_price*100)}</strong></div><span>${tr('Ətraflı hesabat','Подробный отчёт','Detailed report')} ↗</span></a>`+html;};
 function setup(){return `<main class="container page pro-local-setup"><span class="eyebrow">RADAZ · LOCALHOST</span><h1>${tr('Lokal administrator hesabı','Локальный администратор','Local administrator account')}</h1><p>${tr('Bu kompüterdə işləyən sayt üçün administrator hesabınızı yaradın. Lokal hesablar və fayllar bu kompüterdə saxlanılır; internet saytındakı baza ayrıca qalır.','Создайте администратора для этого компьютера. Локальная база хранится здесь отдельно от интернет-сайта.','Create an administrator for this computer. Local accounts and files are stored here, separately from the online site.')}</p><section class="card"><form data-form="localSetup">${field(tr('Ad və soyad','Имя','Full name'),'name','','required')}${field('Email','email','','type="email" required')}${field(tr('Şifrə','Пароль','Password'),'password','','type="password" minlength="12" maxlength="128" required autocomplete="new-password"')}${field(tr('Şifrəni təkrar edin','Повторите пароль','Confirm password'),'confirm_password','','type="password" minlength="12" maxlength="128" required autocomplete="new-password"')}<button class="btn btn-primary" type="submit">${tr('Administrator yarat','Создать администратора','Create administrator')}</button></form></section></main>`;}
 R.forms.localSetup=async d=>{const r=await R.request('/auth/local-setup',{method:'POST',body:d});R.state.user={...r.user,role:'doctor',is_owner:true};R.config=await R.request('/config');R.go('/admin/overview');};
 const admin=P.adminPage;P.adminPage=()=>R.state.route==='/admin/clinics'&&owner()?connection():admin();
 const render=R.render;R.render=()=>{if(R.config?.local_setup_required&&!R.state.user){R.$('#app').innerHTML=setup();document.title='RADAZ · Local setup';return;}if(R.state.route==='/clinic-connections'){R.$('#app').innerHTML=R.state.user?connection():R.authPage(false);}else render();if(R.config?.local_mode)R.$('.dashboard-top')?.insertAdjacentHTML('beforeend',`<span class="pro-environment">${tr('Lokal baza','Локальная база','Local database')}</span>`);};
 for(const key of ['login','logout','register']){const fn=R.api[key];R.api[key]=async(...a)=>{cache.clear();clinicId='';return fn(...a);};}
})();
